import{_ as i,o as a,c as l,a8 as o,ao as t,ap as n,aq as r,ar as s,as as c,at as d,au as h,av as p,aw as u,ax as b,ay as m,az as g,aA as f,aB as v,aC as k}from"./chunks/framework.BG9kL4Xs.js";const N=JSON.parse('{"title":"User docs","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-plugin/user-docs.md","filePath":"content/plugins/bcew-plugin/user-docs.md"}'),y={name:"content/plugins/bcew-plugin/user-docs.md"};function x(P,e,w,S,B,_){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="user-docs" tabindex="-1">User docs <a class="header-anchor" href="#user-docs" aria-label="Permalink to “User docs”">​</a></h1><p>This guide covers existing Site Editor features for WordPress site authors and administrators.</p><p>Jump to:</p><ul><li><a href="#notification-banner">Notification Banner</a></li><li><a href="#in-page-navigation">In-Page Navigation</a></li><li><a href="#navigation-block">Navigation Block</a></li><li><a href="#content-security-policy-csp">Content Security Policy (CSP)</a></li><li><a href="#breadcrumb-block">BreadCrumb Block</a></li></ul><h2 id="notification-banner" tabindex="-1">Notification Banner <a class="header-anchor" href="#notification-banner" aria-label="Permalink to “Notification Banner”">​</a></h2><p>Use this tool to enable a Notification Banner at the top of each page of your website. You can choose the text shown in the banner, as well as its background color. HTML markup is also valid if you want to control the format of the text.</p><p>The tool lives in:</p><ul><li>WordPress Admin → Design System → Notification Banner</li></ul><p>Click Save Settings to apply changes, and see a preview below the Banner Preview label.</p><p><img src="'+t+'" alt="Notification Banner HOWTO"></p><h3 id="how-the-banner-tool-works" tabindex="-1">How the banner tool works <a class="header-anchor" href="#how-the-banner-tool-works" aria-label="Permalink to “How the banner tool works”">​</a></h3><ul><li>Enable/Disable the banner using the radio buttons.</li><li>The Banner Content textbox can accept plain text or HTML Markup, such as: <ul><li><strong>strong (bold)</strong></li><li><em>emphasis (italics)</em></li><li><u>underline (use with caution; can confuse links)</u></li><li><s>Strikethrough</s></li><li><mark>Highlighted text</mark></li><li><pre>preformatted text (preserves spaces and line breaks)</pre></li></ul></li><li>Other specialized text markup: <code>&lt;abbr&gt;</code>, <code>&lt;code&gt;</code>, <code>&lt;kbd&gt;</code>, <code>&lt;var&gt;</code>, <code>&lt;sup&gt;</code>, and <code>&lt;sub&gt;</code>.</li><li>List item markup: <code>&lt;ul&gt;</code>, <code>&lt;ol&gt;</code>, <code>&lt;li&gt;</code>, <code>&lt;dl&gt;</code>, <code>&lt;dt&gt;</code>, and <code>&lt;dd&gt;</code>.</li><li>Quotations and citations: <code>&lt;blockquote&gt;</code>, <code>&lt;q&gt;</code>, and <code>&lt;cite&gt;</code>.</li><li>Headings: <code>&lt;H1&gt;</code> through <code>&lt;H6&gt;</code>.</li><li>Choose the background banner color using the color-coded background status colors: <span style="background-color:#f8bb47;color:black;padding:3px;">Warning</span>, <span style="background-color:#ce3e39;color:white;padding:3px;">Danger</span>, <span style="background-color:#42814a;color:white;padding:3px;">Success</span>, or <span style="background-color:#053662;color:white;padding:3px;">Info</span>.</li><li>To hide the banner, simply click &#39;Disable&#39; beside &#39;Enable Banner&#39;.</li></ul><h3 id="notification-banner-recipes" tabindex="-1">Notification Banner recipes <a class="header-anchor" href="#notification-banner-recipes" aria-label="Permalink to “Notification Banner recipes”">​</a></h3><ul><li>Test Site Banner <ul><li>Text: <code>This is the Dev/Test Environment. The content you are viewing is not final and subject to change.</code></li><li>Background color: <span style="background-color:#ce3e39;color:white;padding:3px;">Danger</span></li></ul></li><li>Site under maintenance <ul><li>Text: <code>This site is under maintenance. Please check back periodically for updates</code></li><li>Background color: <span style="background-color:#f8bb47;color:black;padding:3px;">Warning</span></li></ul></li><li>Informational Banner <ul><li>Text: <code>Here are instructions for filling in this form...</code></li><li>Background color: <span style="background-color:#053662;color:white;padding:3px;">Info</span></li></ul></li></ul><h3 id="notification-banner-testing" tabindex="-1">Notification Banner testing <a class="header-anchor" href="#notification-banner-testing" aria-label="Permalink to “Notification Banner testing”">​</a></h3><ol><li>Save Settings.</li><li>Verify the banner preview matches expectations.</li><li>Navigate to your homepage and hard-refresh your browser.</li><li>Verify the text and background color of the banner are correct.</li></ol><p><img src="'+n+'" alt="Show Notification Banner"></p><h2 id="in-page-navigation" tabindex="-1">In-Page Navigation <a class="header-anchor" href="#in-page-navigation" aria-label="Permalink to “In-Page Navigation”">​</a></h2><p>Provides an automatic table of contents for Pages by collecting all H2 headings and presenting numbered jump links.</p><p><img src="'+r+'" alt="In-Page Navigation example"></p><h3 id="when-it-appears" tabindex="-1">When it appears <a class="header-anchor" href="#when-it-appears" aria-label="Permalink to “When it appears”">​</a></h3><ul><li>Only on Page post type.</li><li>Only if at least one H2 exists.</li><li>Enabled per page via a toggle in the editor sidebar.</li></ul><p><img src="'+s+'" alt="In-page Navigation HOWTO"></p><h3 id="in-page-navigation-behavior" tabindex="-1">In-Page Navigation behavior <a class="header-anchor" href="#in-page-navigation-behavior" aria-label="Permalink to “In-Page Navigation behavior”">​</a></h3><ul><li>Renders an aside containing numbered links to each section.</li><li>Shows the optional page excerpt at the top, if set.</li><li>Highlights the active section while scrolling (mobile emphasis).</li><li>Smooth scroll on link click.</li></ul><h3 id="editor-usage" tabindex="-1">Editor usage <a class="header-anchor" href="#editor-usage" aria-label="Permalink to “Editor usage”">​</a></h3><ol><li>Edit a Page.</li><li>Open the “In-page Navigation” panel in the document settings.</li><li>Toggle “Enable in-page navigation” on.</li><li>Update the Page.</li></ol><p><img src="'+c+'" alt="In-page Navigation HOWTO"></p><h3 id="responsive-behavior" tabindex="-1">Responsive behavior <a class="header-anchor" href="#responsive-behavior" aria-label="Permalink to “Responsive behavior”">​</a></h3><ul><li>Desktop (&gt;768px): Expanded list always visible.</li><li>Mobile (≤768px): Sticky bar; toggle button collapses/expands; current section emphasized; background lightens after scroll.</li></ul><p><img src="'+d+'" alt="In-page Navigation mobile view"></p><h3 id="excerpt" tabindex="-1">Excerpt <a class="header-anchor" href="#excerpt" aria-label="Permalink to “Excerpt”">​</a></h3><p>If the Page has an excerpt, it is shown at the top of the navigation for context.</p><h2 id="navigation-block" tabindex="-1">Navigation Block <a class="header-anchor" href="#navigation-block" aria-label="Permalink to “Navigation Block”">​</a></h2><p>Add a site navigation menu to pages and posts. This block extends the WordPress core Navigation block with improved styling, submenu handling, and a mobile overlay menu.</p><p>Find it in:</p><ul><li>Block Inserter (+) → Design System → Navigation</li></ul><p>After inserting the block, select a WordPress Menu in the block settings.</p><p><img src="'+h+'" alt="Add the Navigation Block"></p><h3 id="navigation-block-behavior" tabindex="-1">Navigation Block behavior <a class="header-anchor" href="#navigation-block-behavior" aria-label="Permalink to “Navigation Block behavior”">​</a></h3><ul><li>Uses your existing WordPress Menus: <ul><li>Create or edit menus in WordPress Admin → Appearance → Menus.</li><li>In the block settings, choose which Menu to display.</li></ul></li><li>Enhanced styling for top-level items, nested submenus, editor preview, and mobile menu toggle.</li><li>Responsive behavior: <ul><li>Desktop: inline menu.</li><li>Mobile: optional full-screen overlay with a toggle.</li><li>Overlay behavior is controlled by Overlay Mode and the Mobile Breakpoint.</li></ul></li></ul><p><img src="'+p+'" alt="Mobile navigation overlay"></p><h3 id="key-settings" tabindex="-1">Key settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to “Key settings”">​</a></h3><ul><li>Overlay Mode: <ul><li>Always Overlay: Always show as an overlay with a toggle.</li><li>Mobile Overlay: Switch to overlay below the Mobile Breakpoint.</li><li>Never Overlay: Always show as a standard inline menu.</li></ul></li><li>Mobile Breakpoint: <ul><li>Width at which Mobile Overlay activates (for Mobile Overlay mode).</li><li>Default: 768px.</li><li>Adjustable in the block settings.</li></ul></li><li>Visibility: <ul><li>Show on Desktop: Visible at widths ≥ Mobile Breakpoint.</li><li>Show on Mobile: Visible at widths &lt; Mobile Breakpoint.</li><li>If both are disabled, the menu still renders as a safety fallback to avoid hiding site navigation entirely.</li></ul></li></ul><p><img src="'+u+'" alt="Navigation Block Settings"></p><h3 id="submenus" tabindex="-1">Submenus <a class="header-anchor" href="#submenus" aria-label="Permalink to “Submenus”">​</a></h3><ul><li>Desktop: Open on hover; close when the pointer leaves the submenu area.</li><li>Mobile: Open/close via the arrow toggle next to the parent item.</li><li>Nested submenus are positioned to remain within the viewport.</li><li>Behavior mirrors the core Navigation block for keyboard and screen-reader support.</li></ul><h3 id="usage-tips" tabindex="-1">Usage tips <a class="header-anchor" href="#usage-tips" aria-label="Permalink to “Usage tips”">​</a></h3><ul><li>Keep mobile labels concise to prevent wrapping in the overlay.</li><li>Manage structure in Appearance → Menus; items are not added in the block editor.</li><li>Test across breakpoints to confirm overlay and visibility match expectations.</li></ul><h3 id="navigation-block-testing" tabindex="-1">Navigation Block testing <a class="header-anchor" href="#navigation-block-testing" aria-label="Permalink to “Navigation Block testing”">​</a></h3><ol><li>Add the Navigation block to a page or post.</li><li>In the settings panel, select a WordPress Menu.</li><li>Configure Overlay Mode, Mobile Breakpoint, and Visibility.</li><li>View the page and resize: <ul><li>Above the breakpoint: confirm desktop menu and hover submenus.</li><li>Below the breakpoint: confirm mobile toggle, overlay, and tap-to-open submenus.</li></ul></li><li>Confirm the current page is highlighted in the menu.</li></ol><p><img src="'+b+'" alt="Navigation Block HOWTO"></p><h3 id="navigation-block-troubleshooting" tabindex="-1">Navigation Block troubleshooting <a class="header-anchor" href="#navigation-block-troubleshooting" aria-label="Permalink to “Navigation Block troubleshooting”">​</a></h3><ul><li>No menu appears: <ul><li>Ensure a Menu is selected in the block settings.</li><li>Verify the selected Menu has items in Appearance → Menus.</li></ul></li><li>Overlay toggle not visible on mobile: <ul><li>Set Overlay Mode to Mobile Overlay or Always Overlay.</li><li>Ensure Show on Mobile is enabled and the breakpoint is appropriate.</li></ul></li><li>Can’t hide the menu entirely: both visibility toggles off still render the block as a safety fallback.</li></ul><h2 id="content-security-policy-csp" tabindex="-1">Content Security Policy (CSP) <a class="header-anchor" href="#content-security-policy-csp" aria-label="Permalink to “Content Security Policy (CSP)”">​</a></h2><p>Use this tool to control which sources your WordPress site can load for scripts, styles, images, fonts, media, XHR/WebSocket connections, and frames. Tight CSP rules improve security and reduce the risk of cross-site scripting (XSS).</p><p>The tool lives in:</p><ul><li>WordPress Admin → Design System → Content Security Policy</li></ul><p>Click Save Settings to apply changes.</p><p><img src="'+m+'" alt="CSP Howto"></p><h3 id="how-the-form-works" tabindex="-1">How the form works <a class="header-anchor" href="#how-the-form-works" aria-label="Permalink to “How the form works”">​</a></h3><ul><li>Each field accepts a space-separated allowlist of sources (no commas).</li><li>If a field is left empty, the plugin uses its built-in defaults (shown as helper text under each label).</li><li>You can add: <ul><li>Keywords: <code>&#39;self&#39;</code> <code>&#39;none&#39;</code> <code>&#39;unsafe-inline&#39;</code> <code>&#39;unsafe-eval&#39;</code> <code>data:</code> <code>blob:</code> <code>https:</code></li><li>Hosts: <code>example.com</code> <code>sub.example.com</code></li><li>Wildcards: <code>*.example.com</code></li></ul></li><li>Use the least-privilege set you can. Prefer HTTPS. Avoid <code>&#39;unsafe-inline&#39;</code> and <code>&#39;unsafe-eval&#39;</code> when possible.</li></ul><p>To revert a directive to defaults, clear the field and Save Settings. To block a type entirely, enter <code>&#39;none&#39;</code>.</p><h3 id="directive-reference" tabindex="-1">Directive reference <a class="header-anchor" href="#directive-reference" aria-label="Permalink to “Directive reference”">​</a></h3><p>The defaults shown in the UI include the design system’s domains (e.g., gov.bc.ca, twimg.com, flickr domains, and YouTube for embeds).</p><h4 id="default-src-policy" tabindex="-1">Default-src Policy <a class="header-anchor" href="#default-src-policy" aria-label="Permalink to “Default-src Policy”">​</a></h4><ul><li>Fallback for all resource types without an explicit directive.</li><li>Keep minimal. Add broad hosts here only if you can’t scope them to a more specific directive.</li><li>Example additions: <code>https: cdn.example.com</code></li></ul><h4 id="script-src-policy" tabindex="-1">Script-src Policy <a class="header-anchor" href="#script-src-policy" aria-label="Permalink to “Script-src Policy”">​</a></h4><ul><li>JavaScript files and inline JS.</li><li>Prefer hosted files over inline scripts. Remove &#39;unsafe-inline&#39;/&#39;unsafe-eval&#39; if your site doesn’t require them.</li><li>Example additions: <code>cdn.jsdelivr.net cdn.skypack.dev www.googletagmanager.com www.google-analytics.com</code></li></ul><h4 id="style-src-policy" tabindex="-1">Style-src Policy <a class="header-anchor" href="#style-src-policy" aria-label="Permalink to “Style-src Policy”">​</a></h4><ul><li>CSS files and inline styles.</li><li>If you must allow inline styles, keep &#39;unsafe-inline&#39;. Consider using hashed inline styles instead of broad allowance.</li><li>Example additions: <code>fonts.googleapis.com cdn.jsdelivr.net</code></li></ul><h4 id="connect-src-policy" tabindex="-1">Connect-src Policy <a class="header-anchor" href="#connect-src-policy" aria-label="Permalink to “Connect-src Policy”">​</a></h4><ul><li>Fetch/XHR, WebSocket, EventSource, analytics beacons, and GraphQL endpoints.</li><li>Example additions: <code>api.example.com *.sentry.io</code></li></ul><h4 id="img-src-policy" tabindex="-1">Img-src Policy <a class="header-anchor" href="#img-src-policy" aria-label="Permalink to “Img-src Policy”">​</a></h4><ul><li>Images and favicons. data: allows inline base64 images.</li><li>Example additions: <code>i.ytimg.com cdn.example.com data:</code></li></ul><h4 id="font-src-policy" tabindex="-1">Font-src Policy <a class="header-anchor" href="#font-src-policy" aria-label="Permalink to “Font-src Policy”">​</a></h4><ul><li>Font files (woff, woff2, ttf). data: enables embedded fonts like <code>data:font/woff2;base64,d09GMgABAAAAAA...&#39;)</code></li><li>Example additions: <code>fonts.gstatic.com data:</code></li></ul><h4 id="media-src-policy" tabindex="-1">Media-src Policy <a class="header-anchor" href="#media-src-policy" aria-label="Permalink to “Media-src Policy”">​</a></h4><ul><li>Audio and video files (not iframes).</li><li>Example additions: <code>media.example.com</code></li></ul><h4 id="frame-src-policy" tabindex="-1">Frame-src Policy <a class="header-anchor" href="#frame-src-policy" aria-label="Permalink to “Frame-src Policy”">​</a></h4><ul><li>Origins allowed in iframes (and workers for some browsers).</li><li>Example additions: <code>*.youtube.com youtu.be *.vimeo.com *.rumble.com</code></li></ul><h3 id="csp-recipes" tabindex="-1">CSP recipes <a class="header-anchor" href="#csp-recipes" aria-label="Permalink to “CSP recipes”">​</a></h3><ul><li>Google Fonts <ul><li>style-src: <code>fonts.googleapis.com</code></li><li>font-src: <code>fonts.gstatic.com data:</code></li></ul></li><li>YouTube/Vimeo embeds <ul><li>frame-src: <code>*.youtube.com youtu.be *.vimeo.com</code></li><li>img-src: <code>i.ytimg.com</code> (for thumbnails)</li></ul></li><li>Mapbox <ul><li>script-src: <code>api.mapbox.com</code></li><li>style-src: <code>api.mapbox.com</code></li><li>img-src: <code>api.mapbox.com</code></li><li>connect-src: <code>events.mapbox.com</code></li></ul></li><li>Generic CDN <ul><li>Add the CDN host to the specific directive you need (script-src, style-src, img-src, etc.), e.g., <code>cdn.example.com</code>.</li></ul></li></ul><h3 id="csp-testing" tabindex="-1">CSP testing <a class="header-anchor" href="#csp-testing" aria-label="Permalink to “CSP testing”">​</a></h3><ol><li>Save Settings.</li><li>Hard-refresh the page in your browser (Shift+Reload).</li><li>Open DevTools → Console. Look for “Refused to connect/script/style from … because it violates the Content Security Policy”.</li><li>Add the blocked origin to the correct directive and save again.</li><li>Repeat until violations are gone.</li></ol><p>If something still doesn’t load, verify the exact hostname in the violation message and add that host (or a wildcard like <code>*.example.com</code>) to the correct directive.</p><p><img src="'+g+'" alt="CSP Frame Source"></p><h3 id="csp-faq" tabindex="-1">CSP FAQ <a class="header-anchor" href="#csp-faq" aria-label="Permalink to “CSP FAQ”">​</a></h3><ul><li>How do I reset to defaults? <ul><li>Clear the field and click Save Settings.</li></ul></li><li>Can I disable a resource type completely? <ul><li>Enter &#39;none&#39; in that directive and save.</li></ul></li><li>Do I need commas? <ul><li>No. Use spaces between entries.</li></ul></li></ul><h2 id="breadcrumb-block" tabindex="-1">BreadCrumb Block <a class="header-anchor" href="#breadcrumb-block" aria-label="Permalink to “BreadCrumb Block”">​</a></h2><p>The BreadCrumb Block outputs a trail representing the current view (for example, Home / Parent / Child). It is especially useful for large sites with nested pages.</p><h3 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h3><p>Place the block near the top of templates or in a Header/Content template part to improve navigation clarity and orientation.</p><p><img src="'+f+'" alt="Using Breadcrumbs"></p><h3 id="editing-experience" tabindex="-1">Editing experience <a class="header-anchor" href="#editing-experience" aria-label="Permalink to “Editing experience”">​</a></h3><p>In the Site Editor or content editor, the block shows the static example Home / Parent / Child. The current context and hierarchy appear only on the front end. The block has no breadcrumb-specific settings.</p><p><img src="'+v+'" alt="Add a Breadcrumb Block"></p><h3 id="front-end-behavior" tabindex="-1">Front-end behavior <a class="header-anchor" href="#front-end-behavior" aria-label="Permalink to “Front-end behavior”">​</a></h3><p>For singular hierarchical content, the trail contains Home, intermediate ancestors, and the current item as plain text. For non-hierarchical singular content, the posts index, search results, archives, and 404 pages, it shows Home followed by the current context. Home and ancestors are links; the current item is not linked. The breadcrumb is not displayed on the front page.</p><h3 id="usage-examples" tabindex="-1">Usage examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to “Usage examples”">​</a></h3><h4 id="add-to-a-template" tabindex="-1">Add to a template <a class="header-anchor" href="#add-to-a-template" aria-label="Permalink to “Add to a template”">​</a></h4><ol><li>Appearance &gt; Editor.</li><li>Open the relevant template or create a Template Part such as Header.</li><li>Insert “BreadCrumb” block below site header.</li><li>Save and view the template on the front end.</li></ol><h4 id="quick-demo-hierarchy" tabindex="-1">Quick demo hierarchy <a class="header-anchor" href="#quick-demo-hierarchy" aria-label="Permalink to “Quick demo hierarchy”">​</a></h4><p>Create three Pages:</p><ul><li>Grandparent (top level)</li><li>Parent (set Parent to Grandparent)</li><li>Child (set Parent to Parent)</li></ul><p>View the Child page with the block placed in the Page template.</p><p><img src="'+k+'" alt="Page Hierarchy"></p><h3 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to “Accessibility”">​</a></h3><ul><li>Uses a navigation landmark with an accessible label.</li><li>Each ancestor is a link; the current item is plain text.</li><li>Keep link text concise; page title changes automatically propagate.</li></ul><h3 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best practices”">​</a></h3><ul><li>Avoid placing multiple breadcrumb blocks on the same template.</li><li>Keep divider style consistent site-wide.</li><li>Do not manually duplicate breadcrumb links in body content.</li></ul><h3 id="breadcrumb-troubleshooting" tabindex="-1">Breadcrumb troubleshooting <a class="header-anchor" href="#breadcrumb-troubleshooting" aria-label="Permalink to “Breadcrumb troubleshooting”">​</a></h3><ul><li>Breadcrumbs missing: Confirm the block is present in the template used by the current view.</li><li>Wrong hierarchy: Verify parent settings for each Page.</li><li>Breadcrumb absent on the front page: This is expected behavior.</li></ul><p>Archives show the current archive title but not a taxonomy ancestor path.</p>',114)])])}const T=i(y,[["render",x]]);export{N as __pageData,T as default};
